var isValidSudoku = function(board) {
    // One set per row, column, and 3x3 box to track seen digits
    const rows = Array(9)
        .fill(null)
        .map(() => new Set());
    const cols = Array(9)
        .fill(null)
        .map(() => new Set());
    const boxes = Array(9)
        .fill(null)
        .map(() => new Set());

    for (let r = 0; r < 9; r++) {
        for (let c = 0; c < 9; c++) {
            const val = board[r][c];

            // Skip empty cells
            if (val === '.') {
                continue;
            }

            // Figure out which 3x3 box this cell belongs to
            const boxIdx = Math.floor(r / 3) * 3 + Math.floor(c / 3);

            // Check if we already saw this digit in same row, col, or box
            const alreadySeen = rows[r].has(val) || cols[c].has(val) || boxes[boxIdx].has(val);
            if (alreadySeen) {
                return false;
            }

            // Record the digit in all three sets
            rows[r].add(val);
            cols[c].add(val);
            boxes[boxIdx].add(val);
        }
    }

    return true;
};

